export type SapiensPose = "walking" | "running" | "standing" | "cycling";
export type SapiensStyle = "colorful" | "duotone" | "outline";
export interface SapiensCharacterSelection {
  pose: SapiensPose;
  gender: "female" | "male";
  style: SapiensStyle;
  hair: number;
  sweater: number;
  trousers: number;
  shoes: number;
}
export interface SapiensCharacterBuilderProps {
  className?: string;
  brand?: string;
  initialPose?: SapiensPose;
  initialGender?: "female" | "male";
  /** Supply your own transparent artwork to extend the reference character set. */
  artwork?: Partial<Record<SapiensPose, string>>;
  /** A separate female set prevents male artwork from leaking into that selection. */
  femaleArtwork?: Partial<Record<SapiensPose, string>>;
  onChange?: (selection: SapiensCharacterSelection) => void;
  onExport?: (selection: SapiensCharacterSelection) => void;
  onPurchase?: () => void;
}

