function PoseIcon({ pose }: { pose: SapiensPose }) {
  if (pose === "cycling") return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-8 5 8H5m5-8h5l4 8M9 5l3 2m0 0 3-4m-3 4-2 2"/><circle cx="15" cy="2" r="1"/></svg>;
  if (pose === "standing") return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="12" cy="4" r="2"/><path d="M12 7v8m0 0-3 7m3-7 3 7M12 8l-5 6m5-6 5 6"/></svg>;
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="14" cy="4" r="2"/><path d={pose === "running" ? "m12 7-4 7 5 2 2 6M8 14l-5 5M11 8l6 3 4-2M12 7 7 6 4 10" : "m12 7-2 8 5 7m-5-7-6 6m8-13 5 5M12 8l-5 4"}/></svg>;
}
function StyleIcon({ style }: { style: SapiensStyle }) {
  if (style === "colorful") return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M12 3a9 9 0 1 0 7 14c-1-2-4 0-4-3s7-1 6-5a9 9 0 0 0-9-6Z"/><circle cx="8" cy="7" r="1"/><circle cx="5" cy="11" r="1"/><circle cx="11" cy="6" r="1"/><circle cx="15" cy="7" r="1"/></svg>;
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="12" cy="12" r="8"/>{style === "duotone" && <path d="M12 4a8 8 0 0 1 0 16Z" fill="currentColor"/>}</svg>;
}

const HAIR_ART = [ARTWORK["running-red"], ARTWORK["running-blond"], ARTWORK["running-orange-red"]] as const;
const SWEATER_ART = [ARTWORK["running-red"], ARTWORK["running-teal"], ARTWORK["running-yellow-blue"]] as const;
const LEG_ART = [ARTWORK["running-yellow-blue"], ARTWORK["running-light-blue"], ARTWORK["running-dark-brown"], ARTWORK["running-yellow"]] as const;

// Dedicated female poses generated to complement the reference illustration.
const FEMALE_ARTWORK: Record<SapiensPose, string> = {
  running: "/sapiens-characters/female-running.webp",
  walking: "/sapiens-characters/female-walking.webp",
  standing: "/sapiens-characters/female-standing.webp",
  cycling: "/sapiens-characters/female-cycling.webp",
};
const FEMALE_COLORS = {
  hair: [null, [58, 35, 31], [175, 80, 40]],
  sweater: [null, [34, 137, 143], [235, 171, 35]],
  trousers: [null, [115, 159, 195], [71, 42, 34], [138, 65, 35]],
  shoes: [null, [127, 43, 66], [103, 35, 48], [29, 132, 116]],
} satisfies Record<Part, readonly (readonly number[] | null)[]>;
const femaleColorCache = new Map<string, string>();

/** Recolor the female's own material pixels, preserving shading and alpha. */
function useFemaleArtwork(selection: SapiensCharacterSelection, override?: string) {
  const source = override || FEMALE_ARTWORK[selection.pose];
  const key = [source, selection.hair, selection.sweater, selection.trousers, selection.shoes].join("|");
  const [rendered, setRendered] = useState<{ key: string; source: string } | null>(null);
  useEffect(() => {
    if (selection.gender !== "female" || override) return;
    let cancelled = false;
    const cached = femaleColorCache.get(key);
    const image = new Image();
    image.onload = () => {
      if (cancelled) return;
      if (cached) { setRendered({ key, source: cached }); return; }
      if (!selection.hair && !selection.sweater && !selection.trousers && !selection.shoes) {
        setRendered({ key, source });
        return;
      }
      const canvas = document.createElement("canvas");
      canvas.width = image.naturalWidth;
      canvas.height = image.naturalHeight;
      const context = canvas.getContext("2d");
      if (!context) return;
      context.drawImage(image, 0, 0);
      const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
      const data = pixels.data;
      for (let offset = 0; offset < data.length; offset += 4) {
        if (!data[offset + 3]) continue;
        const r = data[offset], g = data[offset + 1], b = data[offset + 2];
        const x = (offset / 4 % canvas.width) / canvas.width;
        const y = Math.floor(offset / 4 / canvas.width) / canvas.height;
        let part: Part | null = null;
        if (y < .29 && x > .2 && x < .7 && r < 155 && g < 100 && b < 100 && r > b) part = "hair";
        else if (y > .2 && y < (selection.pose === "cycling" ? .46 : .57) && r > 70 && r > g * 1.5 && b > g * 1.1) part = "sweater";
        else if (y > .38 && b > r * 1.12 && b > g && b < 170 && g > 30) part = "trousers";
        else if (y > .5 && b >= 170 && b > r * 1.1 && g > r * 1.1) part = "shoes";
        if (!part) continue;
        const color = FEMALE_COLORS[part][variant(selection[part], FEMALE_COLORS[part].length)];
        if (!color) continue;
        const shade = Math.max(r, g, b) / (part === "hair" ? 130 : part === "sweater" ? 205 : part === "trousers" ? 115 : 235);
        data[offset] = Math.min(255, color[0] * shade);
        data[offset + 1] = Math.min(255, color[1] * shade);
        data[offset + 2] = Math.min(255, color[2] * shade);
      }
      context.putImageData(pixels, 0, 0);
      const result = canvas.toDataURL("image/png");
      if (femaleColorCache.size >= 8) femaleColorCache.delete(femaleColorCache.keys().next().value!);
      femaleColorCache.set(key, result);
      setRendered({ key, source: result });
    };
    image.src = source;
    return () => { cancelled = true; };
  }, [key, source, override, selection]);
  return {
    source: rendered?.key === key ? rendered.source : source,
    ready: selection.gender !== "female" || !!override || rendered?.key === key,
  };
}

function variant(value: number, count: number) {
  return ((Math.trunc(value) % count) + count) % count;
}
function figureSource(selection: SapiensCharacterSelection) {
  if (selection.pose === "standing" || selection.pose === "walking") return ARTWORK.standing;
  if (selection.pose === "cycling") return ARTWORK.cycling;
  if (selection.sweater === 0) return HAIR_ART[variant(selection.hair, HAIR_ART.length)];
  if (selection.sweater === 1) return SWEATER_ART[1];
  return LEG_ART[variant(selection.trousers, LEG_ART.length)];
}
function partSource(part: Part, value: number) {
  const collection = part === "hair" ? HAIR_ART : part === "sweater" ? SWEATER_ART : LEG_ART;
  return collection[variant(value, collection.length)];
}
/** Preserve exact native artwork for reference combinations; overlay only independently changed parts. */
function overlayParts(selection: SapiensCharacterSelection): Part[] {
  const baseHair = selection.sweater === 0 ? selection.hair : 2;
  const baseLegs = selection.sweater === 2 ? selection.trousers : 0;
  const parts: Part[] = [];
  if (selection.hair !== baseHair) parts.push("hair");
  if (selection.trousers !== baseLegs) parts.push("trousers");
  if (selection.shoes !== baseLegs) parts.push("shoes");
  return parts;
}

function Character({ selection, customSource, gender, outlineId, previousSelection, transitionPart, transitionKey }: { selection: SapiensCharacterSelection; customSource?: string; gender: string; outlineId: string; previousSelection?: SapiensCharacterSelection | null; transitionPart?: Part | null; transitionKey?: number }) {
  return <span style={selection.style === "outline" ? { filter: `url(#${outlineId})` } : undefined}>
    <img src={customSource ?? figureSource(selection)} alt="" draggable={false}/>
    {!customSource && selection.pose === "running" && overlayParts(selection).map((part) => <img key={part} src={partSource(part, selection[part])} alt="" draggable={false} style={{ clipPath: CLIPS[part] }}/>) }
    {!customSource && previousSelection && transitionPart && <img key={transitionKey} className="scb-previous-part" src={partSource(transitionPart, previousSelection[transitionPart])} alt="" draggable={false} style={{ clipPath: transitionPart === "trousers" ? "inset(44.5% 0 0)" : CLIPS[transitionPart] }}/>}
    <span className="scb-caption">{gender} character, {selection.pose}, {selection.style}</span>
  </span>;
}

export default function SapiensCharacterBuilder({ className = "", brand = "sapiens", initialPose = "running", initialGender = "male", artwork, femaleArtwork, onChange, onExport, onPurchase }: SapiensCharacterBuilderProps) {
  const [selection, setSelection] = useState<SapiensCharacterSelection>({ pose: initialPose, gender: initialGender, style: "colorful", hair: 0, sweater: 0, trousers: 0, shoes: 0 });
  const [remixOpen, setRemixOpen] = useState(false);
  const [activePart, setActivePart] = useState<Part>("hair");
  const [exportOpen, setExportOpen] = useState(false);
  const [feedback, setFeedback] = useState("");
  const [transitionKey, setTransitionKey] = useState(0);
  const [transitionPart, setTransitionPart] = useState<Part | null>(null);
  const [previousSelection, setPreviousSelection] = useState<SapiensCharacterSelection | null>(null);
  const [exporting, setExporting] = useState(false);
  const id = useId();
  const mounted = useRef(false);
  const busy = useRef(false);
  const remixTrigger = useRef<HTMLButtonElement | null>(null);
  const exportTrigger = useRef<HTMLButtonElement | null>(null);
  const femaleRender = useFemaleArtwork(selection, femaleArtwork?.[selection.pose]?.trim());
  const femaleSource = femaleRender.source;
  const customSource = selection.gender === "female" ? femaleSource : artwork?.[selection.pose]?.trim() || undefined;
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);
  const outlineId = `sapiens-outline-${id.replace(/:/g, "")}`;

  function update(next: Partial<SapiensCharacterSelection>) {
    const value = { ...selection, ...next };
    setSelection(value);
    setFeedback("");
    onChange?.(value);
  }
  function changePose(pose: SapiensPose) {
    setTransitionPart(null);
    setPreviousSelection(null);
    update({ pose });
    setRemixOpen(false);
    setTransitionKey((value) => value + 1);
  }
  function changeGender(gender: SapiensCharacterSelection["gender"]) {
    setTransitionPart(null);
    setPreviousSelection(null);
    update({ gender });
    setTransitionKey((value) => value + 1);
  }
  function cycle(part: Part, direction = 1) {
    const value = variant(selection[part] + direction, VARIANT_COUNTS[part]);
    setPreviousSelection(selection);
    setTransitionPart(selection.gender === "female" ? null : part);
    update({ [part]: value, ...(part === "trousers" ? { shoes: value } : {}), ...(selection.gender === "male" && selection.pose !== "running" ? { pose: "running" as const } : {}) });
    setTransitionKey((value) => value + 1);
  }
  function closeRemix() {
    setRemixOpen(false);
    remixTrigger.current?.focus();
  }
  function closeExport() {
    setExportOpen(false);
    exportTrigger.current?.focus();
  }
  function purchase() {
    if (onPurchase) onPurchase();
    else {
      setRemixOpen(true);
      setFeedback("Explore the character library: choose a pose and remix the colors.");
    }
  }

  async function download(format: "png" | "svg") {
    if (busy.current || !femaleRender.ready) return;
    busy.current = true;
    closeExport();
    setFeedback("");
    setExporting(true);
    try {
      const canvas = document.createElement("canvas");
      canvas.width = 1000;
      canvas.height = 1000;
      const context = canvas.getContext("2d");
      if (!context) throw new Error("Canvas unavailable");
      if (selection.style === "duotone") context.filter = "grayscale(1) sepia(.9) saturate(3) hue-rotate(306deg)";
      const load = (source: string) => new Promise<HTMLImageElement>((resolve, reject) => {
        const image = new Image();
        image.crossOrigin = "anonymous";
        image.onload = () => resolve(image);
        image.onerror = reject;
        image.src = source;
      });
      if (selection.pose === "walking" && selection.gender === "male") {
        context.translate(500, 480);
        context.rotate(-5 * Math.PI / 180);
        context.translate(-500, -500);
      }
      const figure = await load(customSource ?? figureSource(selection));
      const figureScale = Math.min(1000 / figure.naturalWidth, 1000 / figure.naturalHeight);
      context.drawImage(figure, (1000 - figure.naturalWidth * figureScale) / 2, (1000 - figure.naturalHeight * figureScale) / 2, figure.naturalWidth * figureScale, figure.naturalHeight * figureScale);
      if (!customSource && selection.pose === "running") {
        for (const part of overlayParts(selection)) {
          const points = CLIPS[part].slice(8, -1).split(",").map((point) => point.trim().split(" ").map((value) => parseFloat(value) * 10));
          context.save();
          context.beginPath();
          points.forEach(([x, y], index) => index ? context.lineTo(x, y) : context.moveTo(x, y));
          context.closePath();
          context.clip();
          context.drawImage(await load(partSource(part, selection[part])), 0, 0, 1000, 1000);
          context.restore();
        }
      }
      if (selection.style === "outline") {
        const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
        const original = new Uint8ClampedArray(pixels.data);
        const luminance = (offset: number) => original[offset] * .299 + original[offset + 1] * .587 + original[offset + 2] * .114;
        for (let y = 1; y < canvas.height - 1; y++) {
          for (let x = 1; x < canvas.width - 1; x++) {
            const offset = (y * canvas.width + x) * 4;
            if (!original[offset + 3]) continue;
            let edge = 8 * luminance(offset);
            for (let row = -1; row <= 1; row++) {
              for (let column = -1; column <= 1; column++) {
                if (row || column) edge -= luminance(((y + row) * canvas.width + x + column) * 4);
              }
            }
            const shade = Math.max(0, Math.min(255, 255 - Math.abs(edge)));
            pixels.data[offset] = pixels.data[offset + 1] = pixels.data[offset + 2] = shade;
          }
        }
        context.putImageData(pixels, 0, 0);
      }
      const png = canvas.toDataURL("image/png");
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000"><image href="${png}" width="1000" height="1000"/></svg>`;
      const url = format === "svg" ? URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" })) : png;
      const link = document.createElement("a");
      link.href = url;
      link.download = `${brand}-${selection.gender}-${selection.pose}.${format}`;
      link.click();
      if (format === "svg") setTimeout(() => URL.revokeObjectURL(url), 1000);
      onExport?.(selection);
      if (mounted.current) setFeedback(`${format.toUpperCase()} exported. Your character is ready to use.`);
    } catch { if (mounted.current) setFeedback("The artwork couldn’t be exported. Please try again."); }
    finally { busy.current = false; if (mounted.current) setExporting(false); }
  }

  return <section className={`scb-root scb-live relative w-full overflow-hidden ${className}`} aria-label={`${brand} character builder`} onKeyDown={(event) => {
    if (event.key === "Escape") {
      if (exportOpen || remixOpen) {
        event.preventDefault();
        event.stopPropagation();
      }
      if (exportOpen) closeExport();
      else if (remixOpen) closeRemix();
      setFeedback("");
    }
  }}>
    <ComponentStyles css={CSS}/>
    <svg width="0" height="0" className="absolute" aria-hidden="true"><defs><filter id={outlineId} colorInterpolationFilters="sRGB"><feColorMatrix type="saturate" values="0"/><feConvolveMatrix order="3" kernelMatrix="-1 -1 -1 -1 8 -1 -1 -1 -1" preserveAlpha="true"/><feComponentTransfer><feFuncR type="linear" slope="-1" intercept="1"/><feFuncG type="linear" slope="-1" intercept="1"/><feFuncB type="linear" slope="-1" intercept="1"/></feComponentTransfer></filter></defs></svg>
    <div className="scb-stage" style={{ backgroundImage: `url(${BACKDROP})`, backgroundSize: "100% 100%" }}>
      <div className="scb-board">
        <div className="scb-brand">{brand === "sapiens" ? <img className="scb-brand-mark" src={BRAND_MARK} alt="sapiens"/> : <><img src={AVATAR} alt=""/><span>{brand}</span></>}</div>
        <div className="scb-genders" role="group" aria-label="Character appearance">{(["female", "male"] as const).map((option) => <button key={option} type="button" className="scb-button scb-gender" data-active={selection.gender === option} aria-pressed={selection.gender === option} onClick={() => changeGender(option)}><span aria-hidden="true">{option === "female" ? "♀" : "♂"}</span>{option === "female" ? "Female" : "Male"}</button>)}</div>
        <div className="scb-export"><button type="button" className="scb-button scb-pill" aria-expanded={exportOpen} aria-controls={`${id}-export`} disabled={exporting || !femaleRender.ready} onClick={(event) => { exportTrigger.current = event.currentTarget; setExportOpen((value) => !value); }}>{exporting ? "Exporting…" : "Export"} <span aria-hidden="true">⌄</span></button>{exportOpen && <div id={`${id}-export`} className="scb-export-menu"><button type="button" className="scb-button" onClick={() => void download("png")}>Download PNG</button><button type="button" className="scb-button" onClick={() => void download("svg")}>Download SVG</button></div>}</div>
        <div className="scb-poses" role="group" aria-label="Character pose"><div className="scb-options-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="9" r="2"/><path d="M7 18v-2a5 5 0 0 1 10 0v2"/></svg></div>{POSES.map((pose) => <button type="button" key={pose} className="scb-button scb-option" data-active={selection.pose === pose} aria-pressed={selection.pose === pose} onClick={() => changePose(pose)}><span className="scb-circle"><PoseIcon pose={pose}/></span><span>{pose[0].toUpperCase() + pose.slice(1)}</span></button>)}</div>
        <button className="scb-button scb-character" type="button" data-kind={transitionPart ? "part" : "pose"} data-turn={transitionKey ? transitionKey % 2 + 1 : 0} data-pose={selection.pose} data-style={selection.style} data-gender={selection.gender} data-red={!selection.sweater} aria-label="Remix character appearance" aria-expanded={remixOpen} aria-controls={`${id}-remix`} onClick={(event) => { remixTrigger.current = event.currentTarget; setRemixOpen((value) => !value); }}><Character selection={selection} customSource={customSource} gender={selection.gender} outlineId={outlineId} previousSelection={previousSelection} transitionPart={transitionPart} transitionKey={transitionKey}/></button>
        <div className="scb-styles" role="group" aria-label="Illustration style"><div className="scb-options-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="m12 3 6 6-6 6-6-6 6-6ZM5 18h14M9 21h6"/></svg></div>{STYLES.map((style) => <button type="button" key={style} className="scb-button scb-option" data-active={selection.style === style} aria-pressed={selection.style === style} onClick={() => update({ style })}><span className="scb-circle"><StyleIcon style={style}/></span><span>{style[0].toUpperCase() + style.slice(1)}</span></button>)}</div>
        {remixOpen && <div id={`${id}-remix`} className="scb-remix" aria-label="Remix character parts"><div className="scb-remix-header"><span>Remix</span><button type="button" className="scb-button" aria-label="Close remix" onClick={closeRemix}>×</button></div>{REMIX_PARTS.map((part) => <div key={part} className="scb-part" data-part={part} data-active={activePart === part}><button type="button" className="scb-button scb-part-arrow" data-dir="previous" aria-label={`Previous ${PART_LABELS[part].toLowerCase()}`} onClick={() => cycle(part, -1)}>‹</button><button type="button" className="scb-button scb-part-select" aria-label={`Customize ${PART_LABELS[part].toLowerCase()}`} aria-pressed={activePart === part} onClick={() => { setActivePart(part); if (selection.gender === "male" && selection.pose !== "running") update({ pose: "running" }); }}><img src={selection.gender === "female" ? femaleSource : partSource(part, selection[part])} alt="" draggable={false}/></button><button type="button" className="scb-button scb-part-arrow" data-dir="next" aria-label={`Next ${PART_LABELS[part].toLowerCase()}`} onClick={() => cycle(part)}>›</button></div>)}</div>}
        <button type="button" className="scb-button scb-pill scb-purchase" onClick={purchase}>Purchase Full Library</button>
        {feedback && <div className="scb-feedback" role="status">{feedback}</div>}
      </div>
    </div>
    <div className="scb-mobile-controls" aria-label="Character customization controls">
      <fieldset><legend>Pose</legend><div className="scb-mobile-row scb-mobile-poses">{POSES.map((pose) => <button key={pose} type="button" className="scb-button scb-mobile-button" aria-pressed={selection.pose === pose} onClick={() => changePose(pose)}><PoseIcon pose={pose}/>{pose[0].toUpperCase() + pose.slice(1)}</button>)}</div></fieldset>
      <fieldset><legend>Appearance</legend><div className="scb-mobile-row">{(["female", "male"] as const).map((gender) => <button key={gender} type="button" className="scb-button scb-mobile-button" aria-pressed={selection.gender === gender} onClick={() => changeGender(gender)}>{gender === "female" ? "♀ Female" : "♂ Male"}</button>)}</div></fieldset>
      <fieldset><legend>Illustration style</legend><div className="scb-mobile-row">{STYLES.map((style) => <button key={style} type="button" className="scb-button scb-mobile-button" aria-pressed={selection.style === style} onClick={() => update({ style })}><StyleIcon style={style}/>{style[0].toUpperCase() + style.slice(1)}</button>)}</div></fieldset>
      <div className="scb-mobile-row"><button type="button" className="scb-button scb-mobile-button" aria-expanded={remixOpen} aria-controls={`${id}-mobile-remix`} onClick={(event) => { remixTrigger.current = event.currentTarget; setRemixOpen((value) => !value); }}>Remix clothing</button><button type="button" className="scb-button scb-mobile-button" disabled={exporting || !femaleRender.ready} aria-expanded={exportOpen} aria-controls={`${id}-mobile-export`} onClick={(event) => { exportTrigger.current = event.currentTarget; setExportOpen((value) => !value); }}>{exporting ? "Exporting…" : "Export character"}</button></div>
      {remixOpen && <div id={`${id}-mobile-remix`} className="scb-mobile-parts">{REMIX_PARTS.map((part) => <div key={part} className="scb-mobile-part"><span>{PART_LABELS[part]}</span><div><button type="button" className="scb-button scb-mobile-button" aria-label={`Previous ${PART_LABELS[part].toLowerCase()}`} onClick={() => cycle(part, -1)}>‹</button><span className="scb-mobile-variant">{selection[part] + 1} / {VARIANT_COUNTS[part]}</span><button type="button" className="scb-button scb-mobile-button" aria-label={`Next ${PART_LABELS[part].toLowerCase()}`} onClick={() => cycle(part)}>›</button></div></div>)}<button type="button" className="scb-button scb-mobile-button" onClick={closeRemix}>Done</button></div>}
      {exportOpen && <div id={`${id}-mobile-export`} className="scb-mobile-row"><button type="button" className="scb-button scb-mobile-button" onClick={() => void download("png")}>Download PNG</button><button type="button" className="scb-button scb-mobile-button" onClick={() => void download("svg")}>Download SVG</button></div>}
      <button type="button" className="scb-button scb-pill scb-mobile-buy" onClick={purchase}>Purchase Full Library</button>
      {feedback && <p className="scb-mobile-feedback" role="status">{feedback}</p>}
    </div>
  </section>;
}

export function SapiensCharacterBuilderThumbnail({ className = "", previewStep = 0 }: { className?: string; previewStep?: number }) {
  const pose = previewStep >= 2 ? (previewStep % 2 ? "cycling" : "standing") : "running";
  const selection: SapiensCharacterSelection = { pose, gender: "male", style: "colorful", hair: previewStep ? 2 : 0, sweater: previewStep ? 2 : 0, trousers: previewStep ? 3 : 0, shoes: previewStep ? 3 : 0 };
  return <div className={`scb-root scb-thumbnail pointer-events-none w-full overflow-hidden ${className}`} aria-hidden="true" inert><ComponentStyles css={CSS}/><div className="scb-stage" style={{ backgroundImage: `url(${BACKDROP})`, backgroundSize: "100% 100%" }}><div className="scb-board"><div className="scb-brand"><img className="scb-brand-mark" src={BRAND_MARK} alt=""/></div><div className="scb-genders"><span className="scb-gender"><span>♀</span>Female</span><span className="scb-gender" data-active="true"><span>♂</span>Male</span></div><div className="scb-export"><span className="scb-pill">Export ⌄</span></div><div className="scb-poses"><div className="scb-options-label">♙</div>{POSES.map((option) => <div className="scb-option" key={option} data-active={pose === option}><span className="scb-circle"><PoseIcon pose={option}/></span><span>{option[0].toUpperCase() + option.slice(1)}</span></div>)}</div><div className="scb-character" data-pose={pose}><Character selection={selection} gender="male" outlineId=""/></div><div className="scb-styles"><div className="scb-options-label">♧</div>{STYLES.map((style) => <div className="scb-option" key={style} data-active={style === "colorful"}><span className="scb-circle"><StyleIcon style={style}/></span><span>{style[0].toUpperCase() + style.slice(1)}</span></div>)}</div><span className="scb-pill scb-purchase">Purchase Full Library</span></div></div></div>;
}
